def test_post_api_wallet_withdrawals_submit_and_admin_approve():
    # Generate a unique payout_reference to avoid collisions
    random_suffix = str(uuid.uuid4())
    payout_reference = f"TESTSPRITE-TC012-{random_suffix}"
    withdrawal_payload = {
        "amount_egp": 200.00,
        "payout_reference": payout_reference
    }

    driver_headers = {
        "Authorization": f"Bearer {DRIVER_TOKEN}",
        "Content-Type": "application/json"
    }

    admin_headers = {
        "Authorization": f"Bearer {ADMIN_TOKEN}",
        "Content-Type": "application/json"
    }

    withdrawal_id = None

    try:
        # DRIVER submits a withdrawal request
        resp = requests.post(
            f"{BASE_URL}/api/wallet/withdrawals",
            json=withdrawal_payload,
            headers=driver_headers,
            timeout=30
        )
        assert resp.status_code == 201, f"Expected 201 Created but got {resp.status_code} with body {resp.text}"
        json_response = resp.json()
        withdrawal_id = json_response.get("id")
        assert withdrawal_id is not None, "Response JSON missing 'id' field"

        # ADMIN approves the withdrawal request
        approve_resp = requests.post(
            f"{BASE_URL}/api/admin/withdrawal-requests/{withdrawal_id}/approve",
            headers=admin_headers,
            timeout=30
        )
        assert approve_resp.status_code == 200, f"Expected 200 OK but got {approve_resp.status_code} with body {approve_resp.text}"

    finally:
        # Attempt to clean up: If the withdrawal request still exists and is pending, no explicit deletion endpoint mentioned.
        # So no deletion step; typically withdrawal requests are processed/approved from queue and no delete.
        # No action needed here based on PRD for cleanup.
        pass

test_post_api_wallet_withdrawals_submit_and_admin_approve()